    public static float value(int curve,float t) {
        float[] values=switch(curve) {
            case 0 -> CURVE_0;
            case 1 -> CURVE_1;
            case 2 -> CURVE_2;
            case 3 -> CURVE_3;
            case 4 -> CURVE_4;
            case 5 -> CURVE_5;
            case 6 -> CURVE_6;
            case 7 -> CURVE_7;
            case 8 -> CURVE_8;
            case 9 -> CURVE_9;
            case 10 -> CURVE_10;
            default -> throw new IllegalArgumentException();
        };
        float index=TigerISoundProfile.clamp(t,0,1)*256;
        int lo=Math.min((int)index,255);
        return values[lo]+(values[lo+1]-values[lo])*(index-lo);
    }
